"""Produce a reviewable Russian report from the frozen save audit."""
import json,math,statistics as S,collections as C,sys
from pathlib import Path
F=Path(sys.argv[1]).resolve();ROOT=Path(__file__).resolve().parent.parent
r=json.loads((F/'full-audit.json').read_text(encoding='utf8'));p=json.loads((F/'payload.json').read_text(encoding='utf8'));runtime=json.loads((F/'runtime_probe.json').read_text(encoding='utf8'))
cs={x['id']:x for x in r['countries']};us={x['name']:x for x in r['competitions']};clubs={x['id']:x for x in r['clubs']}
def num(x):return f'{x:,.0f}'.replace(',',' ')
def eur(x):return f'{x/1e6:,.2f}'.replace(',',' ')+' млн €'
def pct(n,d):return f'{100*n/max(d,1):.1f}%'
def line(t=''):out.append(t)
def table(headers,rs):
 line('| '+' | '.join(headers)+' |');line('|'+'|'.join(['---']*len(headers))+'|')
 for row in rs:line('| '+' | '.join(map(str,row))+' |')
 line()
# Supplementary diagnostics, using the same archived editions.
h2h=C.defaultdict(C.Counter);archive_totals=C.Counter();archive_zero=C.Counter();national_reputations=C.defaultdict(set)
for raw in (F/'retired.jsonl').open(encoding='utf8'):
 q=json.loads(raw);zero=q.get('matches',0)+sum(x.get('matches',0) for x in q.get('national_stats',[]))==0
 if zero:
  archive_zero['count']+=1;archive_zero['free' if q.get('final_club_id',0)==0 else 'club']+=1;archive_zero['recent20']+=q.get('retired_season',0)>=158
for raw in (F/'editions.jsonl').open(encoding='utf8'):
 e=json.loads(raw)
 if not e.get('national') or e.get('live'):continue
 for identity in e['clubs_by_id'].values():national_reputations[identity['name']].add(identity.get('reputation'))
 for m in e['matches']:
  if not m.get('played') or 1000000001 not in [m['home_id'],m['away_id']]:continue
  home=m['home_id']==1000000001;other=(m['away_id'] if home else m['home_id'])-1000000000;a=m['home_goals'] if home else m['away_goals'];b=m['away_goals'] if home else m['home_goals'];d=h2h[other];d['games']+=1;d['gf']+=a;d['ga']+=b;d['wins' if a>b else 'draws' if a==b else 'losses']+=1
prizes=[]
for u in p['units']:
 if u.get('national'):continue
 a=u['rules'];v=a['prize_rules'];reg=sum(v.get('regular_'+str(i),0) for i in range(1,a['teams_per_division']+1))*a['divisions_count'];po=sum(v.get(k,0) for k in ['playoff_champion','playoff_runner_up','playoff_third','playoff_fourth']);n=a['teams_playoff'];rounds=math.ceil(math.log2(n));po+=sum(n//(2**i)*v.get('playoff_out_'+str(i),0) for i in range(1,rounds-1));wages=sum(c['wages'] for c in r['clubs'] if c['league']==u['name']);prizes.append({'league':u['name'],'regular':reg,'playoff':po,'total':reg+po,'wages_current':wages})
r['economic_flow_estimate']={'units':prizes,'annual_prizes':sum(x['total'] for x in prizes),'current_wages':sum(x['wages_current'] for x in prizes)};r['economic_flow_estimate']['before_other_costs_surplus']=r['economic_flow_estimate']['annual_prizes']-r['economic_flow_estimate']['current_wages'];r['archive']['zero_appearances_detail']=dict(archive_zero);r['russia_head_to_head']=dict(h2h);r['runtime_probe']=runtime;r['cross_checks']=json.loads((F/'cross_checks.json').read_text(encoding='utf8'))
r['reference_checks']=json.loads((F/'reference_checks.json').read_text(encoding='utf8'))
r['national_reputation_history']={name:sorted(values) for name,values in national_reputations.items()}
assert len(national_reputations)==32 and all(len(v)==1 for v in national_reputations.values())
out=[];line('# Полный аудит последнего сейва — 8 ноября 2026');line();line('**Вывод:** мир сохраняет структуру и заметную иерархию сил на дистанции 177 завершённых сезонов. Прежний сценарий «чемпион — и сразу вылет» в высшей лиге не подтвердился. Главные нерешённые вопросы — накопление денег, малоактивный платный рынок и разрастание истории.');line();line('## Что именно проверено');line();line('Последний доступный слот — `autosave`, формат 15, сезон **178**, день **46 из 97**. Внутренняя дата сохранения — **19.10.2026 03:18:39**; исходный файл изменялся 08.11.2026. Более нового слота в доступной базе нет.');line();line(f"Проверены 128 клубов, 32 сборные, {num(sum(x['count'] for x in r['pools'].values()))} действующих игроков, 796 архивных выпусков турниров, {num(r['total_match_records'])} архивных матчей, 2 880 сыгранных матчей текущего сезона и {num(r['archive']['current_branch_retired'])} завершённых карьер текущей ветки. Временная копия и результаты находятся в `{F.relative_to(ROOT).as_posix()}`. Исходный сейв не перезаписывался.");line();line('## 1. Целостность составов, контрактов и сущностей');line();table(['Пул','Игроки','Средний CA','Средний PA','Средний возраст'],[[{'players_by_club':'Основные составы','reserve_players_by_club':'Резерв','youth_players_by_club':'Молодёжь','free_agents':'Свободные агенты'}[k],x['count'],x['ca']['mean'],x['pa']['mean'],x['age']['mean']] for k,x in r['pools'].items()]);line('У всех 128 клубов ровно 20 игроков и допустимые сочетания 2–3 ГК, 7–8 ЗЩ, 5–6 ПЗЩ, 4–5 НАП. Нарушений лимита восьми легионеров нет. Истёкших контрактов в основной клубной заявке нет. Дубликатов ID, неверной принадлежности клубу, CA выше PA, отсутствующих характеристик и характеристик за пределами 1–20 не найдено. Действующие игроки не пересекаются с архивом.');line();line(f"Свободных агентов — 3 460. Нет игроков с CA ниже 70, которые остались свободными пять сезонов и более. Игроков CA 70+ на рынке всего четыре, CA 70–71. Пятилетняя очистка действующего рынка работает; большая масса лишних данных находится в архиве, а не среди вечных активных свободных агентов.");line();line('Дополнительно проверены ссылки журнала трансферов: все ID находят действующего или архивного игрока. Все указанные файлы логотипов текущих клубов существуют. Это проверка наличия ресурсов; корректность отображения в интерфейсе отдельно не измерялась.');line();line('## 2. Сила лиг и устойчивость клубов');line();table(['Лига','Средний CA основной заявки','Средняя репутация','Медианный бюджет'],[[u['name'],f"{S.mean(c['ca_mean'] for c in r['clubs'] if c['league']==u['name']):.2f}",f"{S.mean(c['reputation'] for c in r['clubs'] if c['league']==u['name']):.1f}",eur(S.median(c['budget'] for c in r['clubs'] if c['league']==u['name']))] for u in p['units'] if not u.get('national')]);line('В высшей лиге проверены 176 переходов от чемпионского сезона к следующему: **ни одного попадания действующего чемпиона в зону вылета следующего сезона**. Медианное итоговое место такого чемпиона — 2-е, худшее — 18-е из 32. Повторных чемпионств подряд — 51; максимальная серия — 7 титулов. Корреляция мест клубов в соседних сезонах в среднем 0,74: результаты обладают заметной инерцией.');line();line('Последние 20 чемпионов League One: '+', '.join(f'{n} — {k}' for n,k in us['League One']['last20_champions'])+'.');line();line('В нижних лигах отсутствие повторного чемпиона объясняется повышением: все 176 проверяемых чемпионов League Two, Three и Four не участвовали в следующем выпуске той же лиги. В высшей и четвёртой лигах ежегодно меняются четыре клуба из 32, в двух средних — восемь из 32, поскольку движение идёт в обе стороны. Эти переходы нельзя автоматически считать случайной сменой силы.');line();line('## 3. Матчи и прежние претензии к крупным счетам');line();table(['Турнир','Матчей за последние 20 сезонов','Голов/матч','Ничьи','Одна команда забила 8+','Победа с разницей 6+'],[[u['name'],u['eras']['last20']['matches'],f"{u['eras']['last20']['goals']/u['eras']['last20']['matches']:.2f}",pct(u['eras']['last20']['draws'],u['eras']['last20']['matches']),pct(u['eras']['last20']['8plus'],u['eras']['last20']['matches']),pct(u['eras']['last20']['margin6plus'],u['eras']['last20']['matches'])] for u in sorted(r['competitions'],key=lambda u:(u['national'],u['name']))]);line('Окно — сезоны 158–177; для сборных это 10 турниров, поскольку они проходят раз в два сезона. Текущий незавершённый 178-й сезон в эту таблицу не включён.');line();line('В сохранённой истории не найдено соседних матчей одной серии плей-офф, в которых команды по очереди выигрывали с разницей восемь и более мячей. То есть прежний сценарий 8:0, затем 0:8 здесь не подтвердился. Развороты с разницей четыре и более есть: 65 за всю историю высшей лиги; это существенно менее экстремальный критерий. Полностью пересчитаны 25 632 строки таблиц по сохранённым матчам: очки, В/Н/П, сыгранные матчи, забитые и пропущенные мячи совпали. У всех 8 635 действующих игроков ровно один личный характер.');line();cm=r['current_matches'];line(f"В текущем сезоне: {cm['count']} матчей, {cm['goals']} голов, в среднем {cm['goals']/cm['count']:.2f}. Ударов — {cm['shots_per_match']:.2f} за матч. Голов с ассистентом — **{pct(cm['assisted_goals'],cm['highlight_goals'])}**, с двумя ассистентами — **{pct(cm['two_assist_goals'],cm['highlight_goals'])}**. Голы с пенальти — {pct(cm['penalty_goals'],cm['highlight_goals'])}. Более двух ассистентов, дубликатов ассистента и передач самому себе нет.");line();g=cm['scorer_positions'];line(f"Распределение по основной позиции: НАП — **{pct(g.get('ST',0),sum(g.values()))}**, ПЗЩ — **{pct(g.get('CM',0),sum(g.values()))}**, ЗЩ — **{pct(g.get('CB',0),sum(g.values()))}**. Ориентир 55/30/15 пока соблюдается приблизительно: вклад полузащитников ниже желаемых 30%, защитников — выше 15%. Это вопрос дальнейшей настройки участия в эпизодах; жёсткие квоты голов не нужны. В архивных таблицах найдено 20 вратарских голов за весь прогон: редкая возможность забивать фактически работает.");line();rot=r['rotation'];line(f"Замены присутствуют: по разнице между появлениями и выходами в старте — **{rot['incoming_subs_per_team_match']['mean']:.2f} входящих замен на команду за матч**. В среднем в старте уже использованы {rot['distinct_field_starters']['mean']:.1f} разных полевых игроков клуба. SUB-события намеренно не сохраняются в компактных отчётах матчей, поэтому их отсутствие в архивном списке событий не означает отсутствие замен. Во всех 5 760 отчётах сторон текущего сезона схема 3-2-2; характер только атакующий или оборонительный.");line();line('## 4. Сборные и талант стран');line();nat=next(u for u in r['competitions'] if u['national']);line('За 88 завершённых турниров: '+', '.join(f'{n} — {k}' for n,k in nat['champions'])+'. Финляндия не выиграла ни одного турнира. Первые шесть стран взяли 78 титулов из 88 — 88,6%. Повторных титулов в соседних выпусках — 17, максимальная серия одной сборной — 5. Последние 20 **выпусков**, то есть примерно 40 сезонов: '+', '.join(f'{n} — {k}' for n,k in nat['last20_champions'])+'.');line();table(['Страна','Талант','Игроков в мире','CA 80+','Потенциальная основа 3-2-2, средний CA','Средний PA до 18 лет'],[[c['name'],c['talent'],c['players'],c['ca80_plus'],c['best_322_ca'],c['youth_pa'].get('mean','—')] for c in sorted(r['countries'],key=lambda c:(-c['talent'],c['name']))]);line('«Потенциальная основа» — диагностическая оценка восьми лучших по CA с соблюдением 1+3+2+2. Она не является входом генератора матчей и не учитывает травмы, форму, тактическое поведение и тренерский выбор. Разница стран уже видна: Россия имеет 33 игрока CA 80+, Норвегия — ни одного; оценки основ примерно 84,4 против 76,1. Россия здесь настроена на талант **83**, Норвегия — **74**, Финляндия — **70**.');line();table(['Соперник России','Матчей','Победы / ничьи / поражения','Мячи'],[[cs[i]['name'],h2h[i]['games'],f"{h2h[i]['wins']} / {h2h[i]['draws']} / {h2h[i]['losses']}",f"{h2h[i]['gf']}:{h2h[i]['ga']}"] for i in [2,5,8,10,21,next(i for i,c in cs.items() if c['name']=='Finland')]]);line('В/Н/П здесь считаются по игровому счёту; ничейный матч с победой по пенальти остаётся ничьей в этой таблице. Это фактические результаты разных поколений и тренеров, а не лабораторный процент побед при равных прочих условиях. В частности, 8 побед России над Норвегией в восьми матчах — слишком маленькая выборка для точной оценки вероятности.');line();line('Крупные сенсации не исчезли полностью: среди 5 632 матчей сборных найдено четыре победы с разницей минимум три мяча команды, чей заданный талант ниже на 10+ пунктов. В частности, Австрия обыграла Россию 5:1 в сезоне 136. Это 0,07% всех матчей сборных, а не доля среди одних только неравных пар. По одному такому результату нельзя заключать, что весь турнир случаен; точной причины старого матча без исторических составов и навыков на момент игры не восстановить.');line();line('Текущие регистрации сборных относятся к сезону **176**: турнир 178-го сезона ещё не начался. Некоторые ID в старых заявках уже завершили карьеру. Это не доказательство неполной будущей заявки — новый вызов будет после клубных финалов. Не следует сравнивать сегодняшние максимальные пулы с этими устаревшими регистрациями как с новым отбором.');line();line('В действующем мире нет PA 100; PA 90+ — восемь игроков во всех активных пулах. В архиве данной ветки также нет PA 100. Прежняя проблема частого рождения идеальных игроков в этом прогоне не обнаружена.');line();line('## 5. Репутации, контракты и тренеры');line();line(f"Репутации клубов: {r['reputations']['clubs']['min']}–{r['reputations']['clubs']['max']}, медиана {r['reputations']['clubs']['median']}; клубов с репутацией 1000 нет. Массового упора в потолок не видно. В среднем по лигам репутация убывает от 789 до 501, вместе с силой состава. Репутации действующих игроков — {r['reputations']['players']['min']}–{r['reputations']['players']['max']}. Разные диапазоны клубной и личной известности сами по себе не доказывают ошибку: требования к переходу также зависят от CA и уровня команды.");line();co=r['coaches'];line(f"Тренеры: 128 клубных, 32 тренера сборных, {co['free']} свободных, {co['retired']} завершивших работу. Дубликатов ID и одновременной работы в клубе и сборной нет. За сезоны 169–178: {co['last10_events'].get('appointed',0)} назначений, {co['last10_events'].get('dismissed',0)} увольнений, {co['last10_events'].get('renewed',0)} продления и {co['last10_events'].get('contract_expired',0)} завершение без продления. Система смены тренеров работает. У основного состава нет истёкших контрактов, однако полную обоснованность каждой суммы и каждого продления по одному итоговому сейву доказать нельзя.");line();line('Репутация сборных статична: у каждой из 32 стран за все 88 завершённых турниров сохранено одно и то же значение. Например, Россия — 848, Испания — 840. В текущем коде сборные исключены из сезонного пересчёта репутации. Поэтому жеребьёвка по репутации опирается на исходные оценки, а не на накопленные результаты сборных. Это отдельная недоработка динамики мира.');line();line('## 6. Главная экономическая проблема: деньги накапливаются');line();line(f"Общий остаток денег у клубов — **{eur(r['finance']['total_budget'])}**, медиана — **{eur(r['finance']['budget']['median'])}**. Только один клуб в минусе: CS Universitatea Craiova, {eur(r['finance']['negative'][0]['budget'])}. Самый богатый — {r['finance']['richest'][0]['name']}, {eur(r['finance']['richest'][0]['budget'])}. Медианный текущий фонд зарплат игроков всех клубных пулов и тренера — {eur(r['finance']['wages']['median'])} за сезон.");line();table(['Лига','Призы за места в дивизионах','Плей-офф','Всего призовых за завершённый сезон','Текущие зарплаты'],[[x['league'],eur(x['regular']),eur(x['playoff']),eur(x['total']),eur(x['wages_current'])] for x in prizes]);eco=r['economic_flow_estimate'];line(f"По текущим правилам в мир поступает **{eur(eco['annual_prizes'])} за сезон**, а текущие зарплаты забирают около **{eur(eco['current_wages'])}**. Разница — примерно **{eur(eco['before_other_costs_surplus'])}** до компенсаций и прочих расходов. Это оценка по нынешним ставкам, не восстановленный баланс каждого из 177 прошлых сезонов. Но направление накопления она объясняет: деньги входящим потоком заметно превосходят основной расход.");line();line('Причина не похожа на повторную выплату одного приза: в коде есть отметка выплат за сезон. Проблема структуры экономики — слабый вывод денег из мира. Платные трансферы в основном перераспределяют деньги между клубами. Для ограничения общей денежной массы нужны соразмерные расходы и/или другая калибровка призовых, а не только более дорогие переходы.');line();table(['Клуб','Бюджет','Годовые зарплаты','Запас денег в годовых зарплатах'],[[x['name'],eur(x['budget']),eur(x['wages']),x['cash_to_wage_years']] for x in r['finance']['richest']]);line('## 7. Трансферы: платный рынок слишком узкий');line();tr=r['transfers'];line(f"За сезоны 169–178 зафиксировано {num(tr['last10_in'])} входящих переходов: **{tr['last10_paid']} платных ({pct(tr['last10_paid'],tr['last10_in'])})** и **{num(tr['last10_free'])} бесплатных ({pct(tr['last10_free'],tr['last10_in'])})**. В среднем это лишь {tr['last10_paid']/10/128:.2f} платного приобретения на клуб за сезон. Медианная ненулевая цена — {eur(tr['last10_paid_fees']['median'])}, максимум — {eur(tr['last10_paid_fees']['max'])}.");line();line('В текущем коде есть жёсткая причина: `TransferMarket._seller_can_spare()` отказывает в продаже любого защищённого игрока основы, затем требует запас сверх минимума его позиции. Это действует до обсуждения достаточной цены. Сильный футболист может иметь подходящие амбиции, богатый покупатель — деньги, но сделка не попадёт в переговоры из-за абсолютного запрета продавца. Защита состава полезна, однако в таком виде сильно сужает оборот сильных игроков.');line();line('Направление исправления: разрешать продажу основы при обоснованной цене, желании игрока и обеспеченной замене; проверять итоговую комплектность в конце трансферного окна и атомарность конкретных сделок. Простое снятие защитных проверок опасно возвратом старой проблемы неполных составов.');line();line('## 8. Архив и размер сейва');line();st=r['storage'];outside=sum(st[k]['outside_branch_bytes'] for k in ['save_history_players','save_history_tournaments']);line(f"Файл `games.db` — **{st['file_bytes']/1e9:.2f} ГБ**. Всего в нём {num(st['save_history_players']['all_records'])} записей карьер, но к текущему слоту относятся {num(st['save_history_players']['current_records'])}. Данные других веток занимают как минимум **{outside/1e9:.2f} ГБ** тел записей игроков и турниров. Доступный слот один; эти записи из его головы истории не достижимы. Свободных страниц SQLite — 0: это не уже освобождённое место, которое уберётся одним уплотнением.");line();line(f"В текущем архиве **{num(archive_zero['count'])} игроков с нулём матчей за клубы и сборные**, из них {num(archive_zero['free'])} ушли свободными агентами. Даже за последние 20 сезонов добавилось {num(archive_zero['recent20'])} таких записей. Записи с нулём клубных матчей занимают около **{st['zero_club_appearances_body'][1]/1e6:.0f} МБ**; эта оценка чуть шире, поскольку включает футболистов только с выступлениями за сборную.");line();line('Источник в коде — `GameSession._archive_retired()`: даже не игравший футболист сохраняется, если когда-либо встречался в журнале трансферов. Здесь конфликтуют сохранность старых ссылок и требование удалять неигравших игроков. Решение — минимальная историческая карточка или текстовая запись для ссылки вместо полной карьеры с графиками и характеристиками; полноценный архив оставлять значимым участникам.');line();line(f"В активных разделах отдельно выделяется журнал трансферов: {num(tr['total_events'])} событий, **{st['section_bytes']['transfer_log']/1e6:.1f} МБ** бинарных данных. Он занимает больше половины объёма активных разделов сейва. Стоит выделить исторический журнал из текущего состояния и выдавать его порциями.");line();line('Для уменьшения файла нужны сборка недостижимых веток и последующее безопасное уплотнение базы. Это отдельная операция с резервной копией. Во время аудита данные не удалялись.');line();line('## 9. Настройки выносливости');line();v=r['settings']['values'];table(['Показатель после полной игры','Выносливость 10','Выносливость 20'],[['Готовность',v['condition_after_stamina_10'],v['condition_after_stamina_20']],['Работоспособность',f"{v['fresh_after_stamina_10']*100:.0f}%",f"{v['fresh_after_stamina_20']*100:.0f}%"]]);line('Разница между обычной и максимальной выносливостью сведена всего к трём пунктам. Это следует из действующих настроек, а не из отсутствия характеристики в расчёте. Если нужна яркая разница между выносливостью 10 и 20, эти точки требуют отдельной калибровки. Фактический fingerprint настроек совпал со всеми 2 880 отчётами текущего сезона.');line();line('## 10. Фактическое время обычного дня');line();line(f"На копии выполнены только три дополнительных дня без сохранения результата. Текущий backend — {runtime['backend']}. Загрузка разделов: {runtime['load_ms']:.0f} мс, применение состояния: {runtime['apply_ms']:.0f} мс. Обычные дни с 64 матчами: "+', '.join(f"{x['elapsed_ms']:.0f} мс" for x in runtime['days'])+'. Это синхронный расчёт без отрисовки интерфейса, не измерение видимой пользователю задержки окна.');line();line('Матчи заняли примерно 90–93% времени дня; восстановление игроков — около 35 мс. Работа с историей в этих трёх днях — сотые доли миллисекунды. Поэтому очистка архива важна для размера, обслуживания и загрузки, но сама по себе не обещает многократного ускорения обычного игрового дня. Для ускорения прокрутки основные кандидаты — матчевый расчёт и отдельно отрисовка интерфейса.');line();line('## Что делать следующим');line();line('1. Развести полноценную карьеру и минимальную историческую идентичность; добавить контролируемую очистку недостижимых веток.');line('2. Согласовать призовой поток с расходами, заложить операционные расходы клубов и правила обращения с накопленным капиталом.');line('3. Разрешить обоснованные продажи игроков основы с заменой, сохранив защиту комплектности.');line('4. Уточнить вклад полузащитников в завершение атак и растянуть влияние выносливости между 10 и 20.');line('5. Снова прогнать длинный мир и сравнить финансовую массу, платные сделки, силу сборных и переход чемпиона к следующему сезону.');line();line('## Границы доказательства');line();line('Все исторические выводы относятся к фактически сохранённым матчам и таблицам этой ветки. Текущие характеристики не восстанавливают точные характеристики игрока 100 сезонов назад. Старые отчёты не содержат полноценных составов, замен и всех эпизодов; будущую заявку сборной нельзя оценивать по оставшейся регистрации предыдущего турнира. Рейтинг CA в таблице стран используется только как понятный показатель качества пула, а не как формула результата матча. Корреляция и наблюдаемая частота не заменяют контролируемый эксперимент. Правила игры и исходное сохранение в ходе аудита не менялись.');line();line('Машиночитаемые результаты: `tests/performance/results/save-audit-2026-11-08.json`. Скрипты: `tools/analyze_full_save.py`, `tools/render_full_save_audit.py`; экспорт и runtime-проба находятся в `tests/performance/full_save_*`.')
output=ROOT/'docs/save-audit-2026-11-08.md';output.write_text('\n'.join(out)+'\n',encoding='utf8');(ROOT/'tests/performance/results/save-audit-2026-11-08.json').write_text(json.dumps(r,ensure_ascii=False,indent=2),encoding='utf8');print(output);print('words',len(' '.join(out).split()))
